// ── 목록(AC_UI_LANGS)에 없는 언어: 처음 한 사람이 들어오면 AI가 화면 문구를 번역해 서버에 저장 → 다음 사람부터 즉시 ──
// 실제 언어 코드인지 브라우저 Intl로 확인(없는 코드로 서버를 두드리지 않게)
function acIsLang(l) { try { return /^[a-z]{2,3}$/.test(l) && new Intl.DisplayNames(['en'], { type: 'language' }).of(l).toLowerCase() !== l; } catch (e) { return false; } }
// 그 언어로 쓴 언어 이름(예: id → Indonesia). 언어 선택 칸·명함 언어 목록에 쓰임
function acRegisterLang(l) {
  if (!AC_LANGS[l]) { try { const n = new Intl.DisplayNames([l], { type: 'language' }).of(l); AC_LANGS[l] = n.charAt(0).toUpperCase() + n.slice(1); } catch (e) { AC_LANGS[l] = l.toUpperCase(); } }
  return AC_LANGS[l];
}
const AC_DYN = {};   // 언어 → { 문구키: 번역 }
function acHash(str) { let h = 5381; for (let i = 0; i < str.length; i++) h = (h * 33 + str.charCodeAt(i)) >>> 0; return h.toString(36); }
// 번역 원문 = 영어 화면 문구 전체 + 명함 버튼 문구(card.*). 문구가 바뀌면 해시가 바뀌어 새로 번역됨
function acDynSource() { const src = {}; Object.keys(AC_T).forEach(k => { src[k] = AC_T[k][1]; }); Object.keys(AC_UI.en).forEach(k => { src['card.' + k] = AC_UI.en[k]; }); return src; }
async function acLoadLang(l) {
  if (AC_UI_LANGS.includes(l) || AC_DYN[l]) return true;
  if (!acIsLang(l)) return false;
  acRegisterLang(l);
  const src = acDynSource(), key = 'autocard_dyn_' + l + '_' + acHash(JSON.stringify(src));
  let m = null; try { m = JSON.parse(localStorage.getItem(key) || 'null'); } catch (e) {}
  if (!m) {
    const res = await fetch(AC_WORKER + '/autocard/ui', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ lang: l, src }) });
    const d = await res.json().catch(() => ({}));
    if (!res.ok || !d.strings) return false;
    m = d.strings; try { localStorage.setItem(key, JSON.stringify(m)); } catch (e) {}
  }
  AC_DYN[l] = m;
  const card = {}; Object.keys(AC_UI.en).forEach(k => { card[k] = m['card.' + k] || AC_UI.en[k]; }); AC_UI[l] = card;
  return true;
}

// 화면 언어 정하기: ?ui= → 전에 고른 언어 → 브라우저 언어(목록에 없어도 실제 언어면 자동 번역) → 영어
function acDetectUi() {
  const ok = l => AC_UI_LANGS.includes(l) || acIsLang(l) ? l : '';
  let q = ''; try { q = ok(String(new URLSearchParams(location.search).get('ui') || '').toLowerCase()); } catch (e) {}
  if (q) { try { localStorage.setItem('autocard_ui', q); } catch (e) {} return q; }
  try { const s = ok(localStorage.getItem('autocard_ui') || ''); if (s) return s; } catch (e) {}
  for (const l of (navigator.languages || [navigator.language || ''])) { const m = ok(String(l).slice(0, 2).toLowerCase()); if (m) return m; }
  return 'en';
}
let UI = acDetectUi();
const acUiIsDynamic = () => !AC_UI_LANGS.includes(UI);
if (acUiIsDynamic()) acRegisterLang(UI);
function acSetUi(l) { if (!AC_UI_LANGS.includes(l) && !acIsLang(l)) return; UI = l; if (acUiIsDynamic()) acRegisterLang(l); try { localStorage.setItem('autocard_ui', l); } catch (e) {} document.documentElement.lang = l; }
// t('key', {var}) — 없는 문구는 영어, 그다음 한국어로 대체(자동 번역 언어는 번역이 오기 전까지 영어)
function t(key, vars) {
  const row = AC_T[key]; if (!row) return key;
  const i = AC_UI_LANGS.indexOf(UI);
  let s = (i >= 0 ? row[i] : AC_DYN[UI] && AC_DYN[UI][key]) || row[1] || row[0];
  if (vars) s = s.replace(/\{(\w+)\}/g, (m, k) => vars[k] !== undefined ? vars[k] : m);
  return s;
}
// 가격 표시: 한국어는 "5,900원", 그 외는 "₩5,900"
function acWon(n) { return UI === 'ko' ? n.toLocaleString('ko-KR') + '원' : '₩' + n.toLocaleString('en-US'); }
document.documentElement.lang = UI;
